const tags=new Set(['svg','g','path','rect','circle','ellipse','line','polyline','polygon','defs','linearGradient','radialGradient','stop','clipPath']);
const attributes=new Set(['id','viewBox','width','height','x','y','x1','x2','y1','y2','cx','cy','r','rx','ry','d','points','transform','fill','stroke','stroke-width','stroke-linecap','stroke-linejoin','fill-rule','clip-rule','clip-path','opacity','fill-opacity','stroke-opacity','offset','stop-color','stop-opacity','gradientUnits','gradientTransform','spreadMethod','fx','fy']);
export function sanitizeSVG(text){
 if(text.length>256000)throw Error('SVG exceeds 256 KB');const doc=new DOMParser().parseFromString(text,'image/svg+xml');if(doc.querySelector('parsererror')||doc.documentElement.localName!=='svg')throw Error('Invalid SVG');
 for(const node of [...doc.querySelectorAll('*')]){if(!tags.has(node.localName)){node.remove();continue;}for(const a of [...node.attributes]){if(!attributes.has(a.name)||/javascript:|data:|https?:|@import|expression|var\(/i.test(a.value)||(/url\(/i.test(a.value)&&!/^url\(#[\w-]+\)$/.test(a.value)))node.removeAttribute(a.name);}}
 const svg=doc.documentElement;svg.setAttribute('xmlns','http://www.w3.org/2000/svg');if(!svg.hasAttribute('viewBox')){const w=parseFloat(svg.getAttribute('width'))||1024,h=parseFloat(svg.getAttribute('height'))||1024;svg.setAttribute('viewBox',`0 0 ${Math.max(1,Math.min(8192,w))} ${Math.max(1,Math.min(8192,h))}`);}svg.setAttribute('width','1024');svg.setAttribute('height','1024');return new XMLSerializer().serializeToString(svg);
}
export async function svgBitmap(text){const url=URL.createObjectURL(new Blob([sanitizeSVG(text)],{type:'image/svg+xml'}));try{const image=new Image();image.src=url;await image.decode();return image;}finally{URL.revokeObjectURL(url)}}
